import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class LiveDpsOverlay extends Overlay
{
	private static final double DPS_SMOOTH_SPEED = 16.0;
	private static final double SCALE_SMOOTH_SPEED = 8.0;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private SpoopDpsConfig config;

	private double smoothedDps;
	private double smoothedExpectedDps;
	private double smoothedPeakDps;
	private long lastSmoothNanos;
	private Instant trackedSessionStart;
	private boolean smoothingInitialized;

	LiveDpsOverlay()
	{
		setPosition(OverlayPosition.TOP_RIGHT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showLiveDpsBox())
		{
			return null;
		}

		CombatSession session = combatTracker.getOverlaySession();
		boolean inCombat = combatTracker.isInCombat();

		long frameNanos = System.nanoTime();
		double deltaSeconds = lastSmoothNanos == 0 ? 0 : (frameNanos - lastSmoothNanos) / 1_000_000_000.0;
		lastSmoothNanos = frameNanos;

		if (session == null)
		{
			resetSmoothing(null);
			return DpsMeterRenderer.drawMeter(
				graphics, 0, 0,
				DpsMeterSnapshot.builder().dps(0).inCombat(false).build(),
				config, null, true);
		}

		if (trackedSessionStart == null || !trackedSessionStart.equals(session.getStartTime()))
		{
			resetSmoothing(session);
		}

		DpsMeterSnapshot target = DpsMeterSnapshot.fromSession(session, inCombat);
		if (!smoothingInitialized)
		{
			smoothedDps = target.getDps();
			smoothedExpectedDps = target.getExpectedDps();
			smoothedPeakDps = target.getPeakDps();
			smoothingInitialized = true;
		}
		else if (deltaSeconds > 0)
		{
			smoothedDps = smoothToward(smoothedDps, target.getDps(), deltaSeconds, DPS_SMOOTH_SPEED);
			smoothedExpectedDps = smoothToward(smoothedExpectedDps, target.getExpectedDps(), deltaSeconds, SCALE_SMOOTH_SPEED);
			smoothedPeakDps = smoothToward(smoothedPeakDps, target.getPeakDps(), deltaSeconds, SCALE_SMOOTH_SPEED);
		}

		DpsMeterSnapshot display = DpsMeterSnapshot.builder()
			.subtitle(target.getSubtitle())
			.dps(smoothedDps)
			.expectedDps(smoothedExpectedDps)
			.peakDps(smoothedPeakDps)
			.fightElapsedMs(target.getFightElapsedMs())
			.inCombat(inCombat)
			.boomPercent(target.getBoomPercent())
			.whiffPercent(target.getWhiffPercent())
			.attackCount(target.getAttackCount())
			.build();

		return DpsMeterRenderer.drawMeter(graphics, 0, 0, display, config, null, true);
	}

	private void resetSmoothing(CombatSession session)
	{
		trackedSessionStart = session != null ? session.getStartTime() : null;
		smoothingInitialized = false;
		smoothedDps = 0;
		smoothedExpectedDps = 0;
		smoothedPeakDps = 0;
		lastSmoothNanos = 0;
	}

	private static double smoothToward(double current, double target, double deltaSeconds, double speed)
	{
		double factor = 1.0 - Math.exp(-speed * deltaSeconds);
		return current + (target - current) * factor;
	}
}

package com.spoopdps;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class PartyDpsOverlay extends Overlay
{
	@Inject
	private PartyDpsTracker partyDpsTracker;

	@Inject
	private SpoopDpsConfig config;

	PartyDpsOverlay()
	{
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.partyDps())
		{
			return null;
		}

		List<PartyMemberDpsState> members = partyDpsTracker.getVisibleRemoteMembers();
		if (members.isEmpty())
		{
			return null;
		}

		int x = 0;
		int y = 0;
		int maxWidth = 0;
		int totalHeight = 0;

		for (PartyMemberDpsState member : members)
		{
			Dimension size = DpsMeterRenderer.drawMeter(
				graphics, x, y, member.getSnapshot(), config, member.getDisplayName(), true);
			maxWidth = Math.max(maxWidth, size.width);
			y += size.height + DpsMeterRenderer.ROW_GAP;
			totalHeight = y;
		}

		if (totalHeight > 0)
		{
			totalHeight -= DpsMeterRenderer.ROW_GAP;
		}

		return new Dimension(maxWidth, totalHeight);
	}
}

package com.spoopdps;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

@Singleton
class PartyDpsTracker
{
	private static final long STALE_MS = 15000;

	@Inject
	private PartyService partyService;

	@Inject
	private CombatTracker combatTracker;

	private final Map<Long, PartyMemberDpsState> remoteMembers = new ConcurrentHashMap<>();

	void clear()
	{
		remoteMembers.clear();
	}

	void broadcastLocalState(SpoopDpsConfig config)
	{
		if (!config.partyDps() || !partyService.isInParty())
		{
			return;
		}

		PartyMember localMember = partyService.getLocalMember();
		if (localMember == null)
		{
			return;
		}

		CombatSession session = combatTracker.getOverlaySession();
		boolean inCombat = combatTracker.isInCombat();
		ExpectedDpsEstimate expected = session != null ? session.getExpectedDps() : null;

		SpoopDpsPartyUpdate update = new SpoopDpsPartyUpdate(
			session != null ? session.getDps() : 0,
			expected != null ? expected.getDps() : 0,
			session != null ? session.getPeakRollingDps() : 0,
			inCombat,
			session != null ? session.getElapsedMs() : 0,
			session != null ? session.getHistoryLabel() : "",
			session != null ? session.getBoomPercent() : 0,
			session != null ? session.getWhiffPercent() : 0,
			session != null ? session.getAttackCount() : 0
		);
		partyService.send(update);
	}

	void onPartyUpdate(SpoopDpsPartyUpdate update)
	{
		if (!partyService.isInParty())
		{
			return;
		}

		PartyMember localMember = partyService.getLocalMember();
		if (localMember != null && localMember.getMemberId() == update.getMemberId())
		{
			return;
		}

		PartyMember member = partyService.getMemberById(update.getMemberId());
		if (member == null)
		{
			return;
		}

		String name = member.getDisplayName();
		if (name == null)
		{
			return;
		}

		remoteMembers.put(update.getMemberId(), PartyMemberDpsState.fromUpdate(update, name));
	}

	List<PartyMemberDpsState> getVisibleRemoteMembers()
	{
		List<PartyMemberDpsState> members = new ArrayList<>();
		for (PartyMemberDpsState state : remoteMembers.values())
		{
			if (state.isVisible(STALE_MS))
			{
				members.add(state);
			}
		}
		members.sort(Comparator.comparing(PartyMemberDpsState::getDisplayName, String.CASE_INSENSITIVE_ORDER));
		return members;
	}
}

package com.spoopdps;

import lombok.Getter;

@Getter
class PartyMemberDpsState
{
	private final long memberId;
	private final String displayName;
	private final DpsMeterSnapshot snapshot;
	private final long updatedAtMs;

	PartyMemberDpsState(long memberId, String displayName, DpsMeterSnapshot snapshot, long updatedAtMs)
	{
		this.memberId = memberId;
		this.displayName = displayName;
		this.snapshot = snapshot;
		this.updatedAtMs = updatedAtMs;
	}

	static PartyMemberDpsState fromUpdate(SpoopDpsPartyUpdate update, String displayName)
	{
		DpsMeterSnapshot snapshot = DpsMeterSnapshot.builder()
			.subtitle(update.isInCombat() ? null : update.getTargetLabel())
			.dps(update.getDps())
			.expectedDps(update.getExpectedDps())
			.peakDps(update.getPeakDps())
			.fightElapsedMs(update.getFightElapsedMs())
			.inCombat(update.isInCombat())
			.boomPercent(update.getBoomPercent())
			.whiffPercent(update.getWhiffPercent())
			.attackCount(update.getAttackCount())
			.build();

		return new PartyMemberDpsState(update.getMemberId(), displayName, snapshot, System.currentTimeMillis());
	}

	boolean isVisible(long staleAfterMs)
	{
		if (System.currentTimeMillis() - updatedAtMs > staleAfterMs)
		{
			return false;
		}
		return snapshot.isInCombat() || snapshot.getDps() > 0;
	}
}

package com.spoopdps;

import lombok.Value;

@Value
class PlayerSnapshot
{
	int combatLevel;
	int attack;
	int strength;
	int defence;
	int ranged;
	int magic;
	int hitpoints;

	String getStyleLabel()
	{
		int melee = attack + strength;
		int range = ranged;
		int mage = magic;

		if (range >= melee && range >= mage)
		{
			return "Ranged";
		}
		if (mage >= melee && mage >= range)
		{
			return "Magic";
		}
		return "Melee";
	}
}

