import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;

class SpoopDpsPanel extends PluginPanel
{
	private static final DecimalFormat DPS_FORMAT = new DecimalFormat("#0.0");
	private static final Color TARGET_BAR = new Color(120, 120, 120);

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private SpoopDpsConfig config;

	private final JLabel statusLabel = new JLabel("Out of combat", SwingConstants.LEFT);
	private final JLabel dpsLabel = new JLabel("—", SwingConstants.LEFT);
	private final JLabel summaryLabel = new JLabel(" ");
	private final JLabel styleLabel = new JLabel(" ");
	private final JLabel luckLabel = new JLabel(" ");
	private final JPanel chartSection = new JPanel();
	private final DpsChartPanel dpsChartPanel = new DpsChartPanel();
	private final JLabel efficiencyLabel = new JLabel(" ");
	private final JLabel expectedDpsPrimaryLabel = new JLabel(" ");
	private final JLabel expectedDpsDetailLabel = new JLabel(" ");
	private final JPanel targetsPanel = new JPanel();
	private final JPanel historySummaryPanel = new JPanel();
	private final JPanel historyLogSection = new JPanel();
	private final JPanel historyPanel = new JPanel();
	private final JButton historyLogToggle = new JButton();
	private boolean historyLogExpanded;

	SpoopDpsPanel()
	{
		super(false);
		setLayout(new BorderLayout(0, 0));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel currentFight = buildCurrentFightPanel();
		JPanel targetsSection = buildTargetsSection();
		JPanel historySection = buildHistorySection();
		buildChartSection();

		JPanel center = new JPanel();
		center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
		center.setBackground(ColorScheme.DARK_GRAY_COLOR);
		center.add(currentFight);
		center.add(chartSection);
		center.add(targetsSection);

		add(center, BorderLayout.NORTH);

		JScrollPane historyScroll = new JScrollPane(historySection);
		historyScroll.setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR));
		historyScroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		historyScroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		add(historyScroll, BorderLayout.CENTER);
	}

	void refresh()
	{
		CombatSession session = combatTracker.getActiveSession();
		if (session == null)
		{
			showIdle();
		}
		else
		{
			showSession(session, true);
		}

		rebuildChart(session);
		rebuildTargets(session);
		rebuildHistory();
	}

	private void buildChartSection()
	{
		chartSection.setLayout(new BorderLayout(0, 2));
		chartSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
		chartSection.setBorder(new EmptyBorder(4, 10, 4, 10));

		JLabel title = sectionTitle("DPS over time");
		chartSection.add(title, BorderLayout.NORTH);
		chartSection.add(dpsChartPanel, BorderLayout.CENTER);

		efficiencyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		efficiencyLabel.setFont(efficiencyLabel.getFont().deriveFont(10f));
		efficiencyLabel.setBorder(new EmptyBorder(2, 0, 0, 0));
		expectedDpsPrimaryLabel.setForeground(new Color(100, 180, 255));
		expectedDpsPrimaryLabel.setFont(expectedDpsPrimaryLabel.getFont().deriveFont(10f));
		expectedDpsPrimaryLabel.setBorder(new EmptyBorder(2, 0, 0, 0));
		expectedDpsDetailLabel.setForeground(new Color(100, 180, 255));
		expectedDpsDetailLabel.setFont(expectedDpsDetailLabel.getFont().deriveFont(10f));

		JPanel expectedDpsBlock = new JPanel(new GridLayout(2, 1, 0, 0));
		expectedDpsBlock.setBackground(ColorScheme.DARK_GRAY_COLOR);
		expectedDpsBlock.add(expectedDpsPrimaryLabel);
		expectedDpsBlock.add(expectedDpsDetailLabel);

		JPanel chartFooter = new JPanel(new GridLayout(3, 1, 0, 0));
		chartFooter.setBackground(ColorScheme.DARK_GRAY_COLOR);
		chartFooter.add(efficiencyLabel);
		chartFooter.add(expectedDpsBlock);
		chartSection.add(chartFooter, BorderLayout.SOUTH);
	}

	private void rebuildChart(CombatSession activeSession)
	{
		if (!config.showChart())
		{
			chartSection.setVisible(false);
			return;
		}

		chartSection.setVisible(true);
		CombatSession chartSession = activeSession;
		if (chartSession == null)
		{
			List<CombatSession> history = combatTracker.getHistory();
			if (!history.isEmpty())
			{
				chartSession = history.get(0);
			}
		}

		dpsChartPanel.setSession(chartSession);
		if (chartSession == null)
		{
			efficiencyLabel.setText(" ");
			expectedDpsPrimaryLabel.setText(" ");
			expectedDpsDetailLabel.setText(" ");
			return;
		}

		String efficiency = chartSession.getEfficiencySummary();
		efficiencyLabel.setText(efficiency.isEmpty() ? " " : efficiency);

		if (config.showExpectedDps() && chartSession.getExpectedDps() != null)
		{
			ExpectedDpsEstimate estimate = chartSession.getExpectedDps();
			expectedDpsPrimaryLabel.setText(estimate.getPrimaryLine());
			expectedDpsDetailLabel.setText(estimate.getDetailLine());
		}
		else
		{
			expectedDpsPrimaryLabel.setText(" ");
			expectedDpsDetailLabel.setText(" ");
		}
	}

	private JPanel buildCurrentFightPanel()
	{
		JPanel panel = new JPanel(new BorderLayout(0, 4));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(8, 10, 8, 10));

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(statusLabel.getFont().deriveFont(Font.BOLD, 12f));
		panel.add(statusLabel, BorderLayout.NORTH);

		dpsLabel.setForeground(Color.WHITE);
		dpsLabel.setFont(dpsLabel.getFont().deriveFont(Font.BOLD, 22f));
		panel.add(dpsLabel, BorderLayout.CENTER);

		JPanel meta = new JPanel(new GridLayout(3, 1, 0, 2));
		meta.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		summaryLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		styleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		luckLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		meta.add(summaryLabel);
		meta.add(styleLabel);
		meta.add(luckLabel);
		panel.add(meta, BorderLayout.SOUTH);

		return panel;
	}

	private JPanel buildTargetsSection()
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setBorder(new EmptyBorder(8, 10, 4, 10));

		JLabel title = sectionTitle("Targets");
		wrapper.add(title, BorderLayout.NORTH);

		targetsPanel.setLayout(new GridLayout(0, 1, 0, 6));
		targetsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(targetsPanel, BorderLayout.CENTER);

		return wrapper;
	}

	private JPanel buildHistorySection()
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setBorder(new EmptyBorder(8, 10, 8, 10));

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.add(sectionTitle("History"), BorderLayout.WEST);

		JButton clearButton = new JButton("Clear");
		clearButton.setFocusable(false);
		clearButton.addActionListener(e -> combatTracker.reset());
		header.add(clearButton, BorderLayout.EAST);
		wrapper.add(header, BorderLayout.NORTH);

		JPanel historyContent = new JPanel();
		historyContent.setLayout(new BoxLayout(historyContent, BoxLayout.Y_AXIS));
		historyContent.setBackground(ColorScheme.DARK_GRAY_COLOR);

		historySummaryPanel.setLayout(new BoxLayout(historySummaryPanel, BoxLayout.Y_AXIS));
		historySummaryPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historySummaryPanel.setBorder(new EmptyBorder(0, 0, 4, 0));
		historyContent.add(historySummaryPanel);

		historyLogSection.setLayout(new BoxLayout(historyLogSection, BoxLayout.Y_AXIS));
		historyLogSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historyLogSection.setAlignmentX(Component.LEFT_ALIGNMENT);

		historyLogToggle.setFocusable(false);
		historyLogToggle.setHorizontalAlignment(SwingConstants.LEFT);
		historyLogToggle.setBorder(new EmptyBorder(6, 0, 4, 0));
		historyLogToggle.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historyLogToggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		historyLogToggle.setFont(historyLogToggle.getFont().deriveFont(Font.BOLD, 11f));
		historyLogToggle.setAlignmentX(Component.LEFT_ALIGNMENT);
		historyLogToggle.addActionListener(e -> toggleHistoryLog());
		historyLogSection.add(historyLogToggle);

