	private void showSession(CombatSession session, boolean active)
	{
		statusLabel.setText(active ? "In combat" : "Last fight");
		statusLabel.setForeground(active ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR);

		dpsLabel.setText(DPS_FORMAT.format(session.getDps()) + " DPS");

		summaryLabel.setText(String.format("%s dmg  ·  %s  ·  %d hits (max %d)",
			QuantityFormatter.formatNumber(session.getTotalDamage()),
			session.getFormattedDuration(),
			session.getHitCount(),
			session.getMaxHit()));

		PlayerSnapshot player = session.getPlayerSnapshot();
		styleLabel.setText("CB " + player.getCombatLevel() + "  ·  " + player.getStyleLabel());
		luckLabel.setText(session.getLuckSummary().isEmpty() ? " " : session.getLuckSummary());
	}

	private void showIdle()
	{
		statusLabel.setText("Out of combat");
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		dpsLabel.setText("—");
		summaryLabel.setText("Attack something to start tracking");
		styleLabel.setText(" ");
		luckLabel.setText(" ");
	}

	private void rebuildTargets(CombatSession session)
	{
		targetsPanel.removeAll();

		if (session == null || session.getTargetsByDamage().isEmpty())
		{
			targetsPanel.add(mutedLabel("No targets yet"));
			targetsPanel.revalidate();
			targetsPanel.repaint();
			return;
		}

		long elapsedMs = session.getElapsedMs();
		int totalDamage = session.getTotalDamage();

		for (TargetStats target : session.getTargetsByDamage())
		{
			targetsPanel.add(buildTargetRow(target, elapsedMs, totalDamage, session.isActive()));
		}

		targetsPanel.revalidate();
		targetsPanel.repaint();
	}

	private JPanel buildTargetRow(TargetStats target, long elapsedMs, int totalDamage, boolean active)
	{
		JPanel row = new JPanel(new BorderLayout(0, 2));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);

		String hp = active ? "  ·  " + target.getHpPercent() + "% HP" : "";
		JLabel name = new JLabel(String.format("%s (lvl %d)%s",
			target.getName(), target.getCombatLevel(), hp));
		name.setForeground(Color.WHITE);

		JLabel stats = new JLabel(String.format("%s  ·  %s DPS  ·  %d hits",
			QuantityFormatter.formatNumber(target.getDamage()),
			DPS_FORMAT.format(target.getDps(elapsedMs)),
			target.getHits()));
		stats.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		stats.setFont(stats.getFont().deriveFont(11f));

		JPanel labels = new JPanel(new GridLayout(2, 1, 0, 0));
		labels.setBackground(ColorScheme.DARK_GRAY_COLOR);
		labels.add(name);
		labels.add(stats);
		row.add(labels, BorderLayout.NORTH);

		JProgressBar bar = new JProgressBar(0, 100);
		int share = (int) Math.round(target.getDamageShare(totalDamage));
		bar.setValue(Math.max(0, Math.min(100, share)));
		bar.setString(share + "% of damage");
		styleBar(bar, TARGET_BAR);
		bar.setPreferredSize(new Dimension(0, 12));
		row.add(bar, BorderLayout.SOUTH);

		return row;
	}

	private void rebuildHistory()
	{
		historySummaryPanel.removeAll();
		historyPanel.removeAll();
		List<CombatSession> history = combatTracker.getHistory();

		if (history.isEmpty())
		{
			historySummaryPanel.add(mutedLabel("No fights recorded yet"));
			historyLogSection.setVisible(false);
		}
		else
		{
			historyLogSection.setVisible(true);

			List<EnemyHistorySummary> summaries = combatTracker.getHistorySummaries();
			if (!summaries.isEmpty())
			{
				historySummaryPanel.add(sectionTitle("By target"));
				JPanel summaryStack = new JPanel();
				summaryStack.setLayout(new BoxLayout(summaryStack, BoxLayout.Y_AXIS));
				summaryStack.setBackground(ColorScheme.DARK_GRAY_COLOR);
				summaryStack.setAlignmentX(Component.LEFT_ALIGNMENT);
				for (EnemyHistorySummary summary : summaries)
				{
					summaryStack.add(buildHistorySummaryBox(summary));
				}
				historySummaryPanel.add(summaryStack);
			}

			for (CombatSession session : history)
			{
				historyPanel.add(buildHistoryRow(session));
			}

			updateHistoryLogToggleLabel(history.size());
			historyPanel.setVisible(historyLogExpanded);
		}

		historySummaryPanel.revalidate();
		historySummaryPanel.repaint();
		historyLogSection.revalidate();
		historyLogSection.repaint();
		historyPanel.revalidate();
		historyPanel.repaint();
	}

	private void toggleHistoryLog()
	{
		historyLogExpanded = !historyLogExpanded;
		historyPanel.setVisible(historyLogExpanded);
		updateHistoryLogToggleLabel(combatTracker.getHistory().size());
		historyLogSection.revalidate();
		historyLogSection.repaint();
	}

	private void updateHistoryLogToggleLabel(int fightCount)
	{
		String arrow = historyLogExpanded ? "\u25BC" : "\u25B6";
		String suffix = fightCount == 1 ? " (1 fight)" : " (" + fightCount + " fights)";
		historyLogToggle.setText(arrow + " Fight log" + suffix);
	}

	private JPanel buildHistorySummaryBox(EnemyHistorySummary summary)
	{
		JPanel box = new JPanel(new BorderLayout(8, 0));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(0, 0, 6, 0),
			BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
				new EmptyBorder(8, 10, 8, 10)
			)
		));
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
		box.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		JLabel name = new JLabel(summary.getName());
		name.setForeground(Color.WHITE);
		name.setFont(name.getFont().deriveFont(Font.BOLD, 12f));

		JLabel dps = new JLabel(DPS_FORMAT.format(summary.getAverageDps()) + " avg DPS");
		dps.setForeground(new Color(100, 180, 255));
		dps.setFont(dps.getFont().deriveFont(12f));
		dps.setHorizontalAlignment(SwingConstants.CENTER);

		String killText = summary.getKillCount() == 1 ? "1 kill" : summary.getKillCount() + " kills";
		JLabel kills = new JLabel(killText);
		kills.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		kills.setFont(kills.getFont().deriveFont(11f));
		kills.setHorizontalAlignment(SwingConstants.RIGHT);

		box.add(name, BorderLayout.WEST);
		box.add(dps, BorderLayout.CENTER);
		box.add(kills, BorderLayout.EAST);
		return box;
	}

	private JPanel buildHistoryRow(CombatSession session)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARKER_GRAY_COLOR),
			new EmptyBorder(3, 0, 3, 0)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		JLabel line = new JLabel(String.format("%s  ·  %s DPS  ·  %s dmg  ·  %s",
			session.getHistoryLabel(),
			DPS_FORMAT.format(session.getDps()),
			QuantityFormatter.formatNumber(session.getTotalDamage()),
			session.getFormattedDuration()));
		line.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		line.setFont(line.getFont().deriveFont(13f));
		row.add(line, BorderLayout.CENTER);
		return row;
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 11f));
		label.setBorder(new EmptyBorder(0, 0, 4, 0));
		return label;
	}

	private static JLabel mutedLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		return label;
	}

	private static void styleBar(JProgressBar bar, Color color)
	{
		bar.setForeground(color);
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setBorder(BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR));
		bar.setStringPainted(true);
	}
}

